// filter items if they have the same "ID" or location
function getItemId(feat) {
    return `${feat.start}-${feat.end}`;
}
// filters if successive elements share same start/end
export function filterSuccessiveElementsWithSameStartAndEndCoord(list) {
    return list.filter((item, pos, ary) => !pos || getItemId(item) !== getItemId(ary[pos - 1]));
}
export function ellipses(slug) {
    return slug.length > 20 ? `${slug.slice(0, 20)}...` : slug;
}
export function getStrandStr(strand) {
    return strand === -1 ? '(-)' : strand === 1 ? '(+)' : '';
}
// JSON only serializes null, not undefined; feature fields are hidden by a
// formatDetails callback returning undefined (jexl can't produce null), so when
// persisting we round-trip undefined to null to keep the field hidden after
// reload (detail components filter with `!= null`). see config guide.
export const nullReplacer = (_, v) => v === undefined ? null : v;
// `currentDepth < depth` rather than a `depth <= currentDepth` bail so a config
// with no formatDetails schema at all (depth reads back undefined) formats
// nothing, instead of every level -- NaN comparisons are false either way round
export function formatSubfeatures(obj, depth, parse, currentDepth = 0) {
    if (currentDepth < depth) {
        for (const sub of obj.subfeatures ?? []) {
            formatSubfeatures(sub, depth, parse, currentDepth + 1);
            parse(sub);
        }
    }
}
